190: export function refreshNextAction(project: Project): Project {
191:   const current = project.sections.find((section) => section.status !== "APPROVED") ?? null;
192:   project.currentSectionId = current?.id ?? null;
193:   if (project.product.status !== "APPROVED") {
194:     project.stage = "ORACLE";
195:     project.nextAction = project.product.status === "PROPOSED"
196:       ? "Approve the Oracle proposal, or ask a question"
197:       : "Describe an idea and wake the Oracle";
198:     return project;
199:   }
200:   if (current) {
201:     project.stage = "ARCHITECT";
202:     project.nextAction = `${current.status === "DRAFT" || current.status === "STALE" ? "Review" : "Draft"} ${current.title}`;
203:     return project;
204:   }
205:   if (project.makerScope.status !== "GRANTED") {
206:     project.stage = "ARCHITECT";
207:     project.nextAction = "Grant a separate Maker execution scope";
208:     return project;
209:   }
210:   const makerSucceeded = project.operations.some((operation) => operation.kind === "maker" && operation.status === "SUCCEEDED");
211:   if (!makerSucceeded) {
212:     project.stage = "MAKER";
213:     project.nextAction = "Run the approved Maker unit and inspect the result";
214:     return project;
215:   }
216:   project.stage = "WITNESS";
217:   project.nextAction = project.witnessDrafts.length
218:     ? "Review the Witness drafts"
219:     : "Ask the Witness to review the evidence";
220:   return project;
221: }

