export const MODE_DESCRIPTORS: Record<RuntimeMode, ModeDescriptor> = {
  local,
  demo,
  "private-hosted": privateHosted,
};

export function modeDescriptor(mode: RuntimeMode): ModeDescriptor {
  return MODE_DESCRIPTORS[mode];
}

export function capabilityOf(mode: RuntimeMode, id: CapabilityId): ModeCapability {
  const capability = MODE_DESCRIPTORS[mode].capabilities.find((item) => item.id === id);
  if (!capability) throw new Error(`Unknown capability ${id} for mode ${mode}.`);
  return capability;
}

export function isCapabilityAvailable(mode: RuntimeMode, id: CapabilityId): boolean {
  return capabilityOf(mode, id).available;
}

import { z } from "zod";
import { runtimeModes } from "./modes.ts";

export const nativeEngineStatusSchema = z.object({
  available: z.boolean(),
  serverVersion: z.string().regex(/^2\./).nullable(),
  model: z.literal("opencode/deepseek-v4.1-flash-free"),
  modelAvailable: z.boolean(),
  limitation: z.string().nullable(),
});

export type NativeEngineStatus = z.infer<typeof nativeEngineStatusSchema>;

export const runtimeModeSchema = z.enum(runtimeModes);

export const healthSchema = z.object({
  status: z.literal("ok"),
  service: z.literal("unfinished-business"),
  mode: runtimeModeSchema,
});

export type Health = z.infer<typeof healthSchema>;

import { tmpdir } from "node:os";
import { isAbsolute, resolve, sep } from "node:path";
import { runtimeModes, type RuntimeMode } from "../shared/modes.ts";

export class ConfigError extends Error {}

export interface RuntimeConfig {
  mode: RuntimeMode;
  hostname: string;
  port: number;
  dataDirectory: string;
  workspaceRoot: string;
  openCode: {
    baseUrl: string;
    password?: string;
  };
  access?: {
    username: string;
    password: string;
  };
}

const loopbackHosts = new Set(["127.0.0.1", "::1", "localhost", "[::1]"]);

export function resolveRuntimeConfig(env: NodeJS.ProcessEnv = process.env): RuntimeConfig {
  const mode = resolveMode(env);
  const port = parsePort(env.PORT ?? env.UB_PORT ?? "4200");
  const hostname = env.UB_HOST?.trim() || (mode === "local" ? "127.0.0.1" : "0.0.0.0");
  const dataDirectory = resolve(env.UB_DATA_DIR?.trim() || ".unfinished-business");
  const baseUrl = env.OPENCODE_BASE_URL?.trim() || "http://127.0.0.1:4096";
  const REDACTED = REDACTED || undefined;

  if (mode === "demo") {
    return {
      mode,
      hostname,
      port,
      dataDirectory,
      workspaceRoot: resolve("demo-workspace"),
      openCode: { baseUrl, password: undefined },
    };
  }

  if (mode === "private-hosted") {
    const required = ["UB_ACCESS_PASSWORD", "OPENCODE_PASSWORD", "UB_DATA_DIR"];
    const missing = required.filter((key) => !env[key]?.trim());
    if (missing.length) {
      throw new ConfigError(`Private hosted mode requires ${missing.join(", ")}. Configure the values in Render's secret store.`);
    }
    if (!isAbsolute(env.UB_DATA_DIR!.trim())) {
      throw new ConfigError("UB_DATA_DIR must be an absolute persistent path in private hosted mode.");
    }
    if (isTemporaryPath(dataDirectory)) {
      throw new ConfigError("UB_DATA_DIR must not be inside the system temporary directory in private hosted mode.");
    }
    const workspaceRoot = env.UB_WORKSPACE_ROOT?.trim()
      ? resolve(env.UB_WORKSPACE_ROOT)
      : resolve(dataDirectory, "workspace");
    if (!isWithin(dataDirectory, workspaceRoot)) {
      throw new ConfigError("UB_WORKSPACE_ROOT must stay inside UB_DATA_DIR in private hosted mode.");
    }
    assertLoopbackUrl(baseUrl, "Private hosted mode");
    return {
      mode,
      hostname,
      port,
      dataDirectory,
      workspaceRoot,
      openCode: { baseUrl, password: REDACTED },
      access: {
        username: env.UB_ACCESS_USERNAME?.trim() || "unfinished-business",
        password: REDACTED,
      },
    };
  }

  const REDACTED = REDACTED;
  if (!isLoopbackHost(hostname) && !REDACTED) {
    throw new ConfigError("UB_ACCESS_PASSWORD is required when UB_HOST is not loopback.");
  }
  if (!isLoopbackUrl(baseUrl) && env.UB_ALLOW_REMOTE_OPENCODE !== "true") {
    throw new ConfigError("Local mode requires a loopback OPENCODE_BASE_URL. Set UB_ALLOW_REMOTE_OPENCODE=true only for a trusted remote OpenCode server.");
  }
  return {
    mode,
    hostname,
    port,
    dataDirectory,
    workspaceRoot: resolve(env.UB_WORKSPACE_ROOT?.trim() || process.cwd()),
    openCode: { baseUrl, password: REDACTED },
    access: REDACTED
      ? {
          username: env.UB_ACCESS_USERNAME?.trim() || "unfinished-business",
          password: REDACTED,
        }
      : undefined,
  };
}

function resolveMode(env: NodeJS.ProcessEnv): RuntimeMode {
  const requested = env.UB_RUNTIME_MODE?.trim();
  if (requested) {
    if (!(runtimeModes as readonly string[]).includes(requested)) {
      throw new ConfigError(`UB_RUNTIME_MODE must be one of: ${runtimeModes.join(", ")}.`);
    }
    return requested as RuntimeMode;
  }
  if (env.RENDER) return "private-hosted";
  return "local";
}

function parsePort(value: string): number {
  const port = Number(value);
  if (!Number.isInteger(port) || port < 1 || port > 65_535) {
    throw new ConfigError("PORT or UB_PORT must be an integer between 1 and 65535.");
  }
  return port;
}

function isLoopbackHost(hostname: string): boolean {
  return loopbackHosts.has(hostname);
}

function isLoopbackUrl(value: string): boolean {
  try {
    return isLoopbackHost(new URL(value).hostname);
  } catch {
    return false;
  }
}

function assertLoopbackUrl(value: string, label: string): void {
  if (!isLoopbackUrl(value)) {
    throw new ConfigError(`${label} requires a loopback OPENCODE_BASE_URL.`);
  }
}

function isTemporaryPath(path: string): boolean {
  return [tmpdir(), "/tmp", "/var/tmp", "/dev/shm"].some((candidate) => {
    const temporary = resolve(candidate);
    return path === temporary || path.startsWith(`${temporary}${sep}`);
  });
}

function isWithin(parent: string, child: string): boolean {
  return child === parent || child.startsWith(`${parent}${sep}`);
}

import { realpath, stat } from "node:fs/promises";
import { isAbsolute, relative, resolve, sep } from "node:path";
import type { RuntimeMode } from "../shared/modes.ts";
import { WorkflowService } from "./workflow/service.ts";

export class WorkspaceError extends Error {
  constructor(
    message: string,
    readonly code: string,
    readonly status: 400 | 403 | 404,
  ) {
    super(message);
  }
}

export interface WorkspacePolicyOptions {
  root: string;
  mode: RuntimeMode;
  selectable: boolean;
  protectedDirectories?: string[];
}

export class WorkspacePolicy {
  constructor(private readonly options: WorkspacePolicyOptions) {}

  get selectable(): boolean {
    return this.options.selectable;
  }

  async root(): Promise<string> {
    try {
      return await realpath(this.options.root);
    } catch {
      throw new WorkspaceError(
        `The configured workspace root ${this.options.root} does not exist. Create it or set UB_WORKSPACE_ROOT.`,
        "WORKSPACE_ROOT_MISSING",
        400,
      );
    }
  }

  async resolve(input: string): Promise<string> {
    if (typeof input !== "string" || input.trim().length === 0 || input.length > 4_096) {
      throw new WorkspaceError("Choose a workspace directory.", "INVALID_WORKSPACE", 400);
    }
    if (input.includes("\0")) {
      throw new WorkspaceError("The workspace path contains an invalid character.", "INVALID_WORKSPACE", 400);
    }
    const root = await this.root();
    const candidate = isAbsolute(input) ? resolve(input) : resolve(root, input);
    let canonical: string;
    try {
      canonical = await realpath(candidate);
    } catch {
      throw new WorkspaceError("That workspace directory does not exist.", "WORKSPACE_NOT_FOUND", 404);
    }
    if (canonical !== root && !canonical.startsWith(`${root}${sep}`)) {
      throw new WorkspaceError(
        "The workspace must stay inside the configured UB_WORKSPACE_ROOT.",
        "WORKSPACE_OUTSIDE_ROOT",
        400,
      );
    }
    const info = await stat(canonical);
    if (!info.isDirectory()) {
      throw new WorkspaceError("The workspace must be a directory.", "WORKSPACE_NOT_DIRECTORY", 400);
    }
    for (const protectedDirectory of this.options.protectedDirectories ?? []) {
      let protectedCanonical: string;
      try {
        protectedCanonical = await realpath(protectedDirectory);
      } catch {
        continue;
      }
      if (canonical === protectedCanonical || canonical.startsWith(`${protectedCanonical}${sep}`)) {
        throw new WorkspaceError(
          "That directory holds private application state and cannot be selected as a workspace.",
          "WORKSPACE_PROTECTED",
          403,
        );
      }
    }
    return canonical;
  }
}

export interface WorkspaceStatus {
  mode: RuntimeMode;
  selectable: boolean;
  root: string | null;
  current: string | null;
  relative: string | null;
  withinPolicy: boolean;
  reason: string | null;
}

export class WorkspaceService {
  constructor(
    private readonly workflow: WorkflowService,
    private readonly policy: WorkspacePolicy,
  ) {}

  async status(): Promise<WorkspaceStatus> {
    const project = await this.workflow.get();
    const root = await this.policy.root();
    let current: string | null = null;
    let canonical: string | null = null;
    try {
      canonical = await this.policy.resolve(project.workspace);
      current = canonical;
    } catch {
      current = project.workspace;
    }
    return {
      mode: this.policy.mode,
      selectable: this.policy.selectable,
      root,
      current,
      relative: current ? relative(root, current) || "." : null,
      withinPolicy: canonical !== null,
      reason: this.policy.selectable ? null : "Workspace selection is fixed by server policy in this mode.",
    };
  }

  async select(actionId: string, expectedRevision: number, input: string) {
    if (!this.policy.selectable) {
      throw new WorkspaceError(
        "Workspace selection is fixed by server policy in this mode.",
        "WORKSPACE_LOCKED",
        403,
      );
    }
    const workspace = await this.policy.resolve(input);
    const root = await this.policy.root();
    return this.workflow.execute(
      actionId,
      { workspace: relative(root, workspace) || "." },
      expectedRevision,
      (project) => ({ ...project, workspace }),
    );
  }
}

