  const safeDirectory = resolve(config.dataDirectory, "spirit-workspace");
  await mkdir(safeDirectory, { recursive: true });
  await mkdir(config.workspaceRoot, { recursive: true });

  const store = new AtomicProjectStore(resolve(config.dataDirectory, "project.json"));
  try {
    await access(store.path);
  } catch {
    await store.initialize(createProject(config.workspaceRoot));
  }

  const sessionToken = process.env.UB_SESSION_TOKEN ?? randomBytes(32).toString("base64url");
  const workflow = new WorkflowService(store);
  const policy = new WorkspacePolicy({
    root: config.workspaceRoot,
    mode: config.mode,
    selectable: config.mode === "local",
    protectedDirectories: [config.dataDirectory],
  });
  const workspace = new WorkspaceService(workflow, policy);
  const experience = new ExperienceService(workflow, store, new OpenCodeSpiritGuide({
    baseUrl: config.openCode.baseUrl,
    password: config.openCode.password,
  }), {
    safeDirectory,
    demoWorkspace: config.workspaceRoot,
    workspaceResolver: policy,
  });

  return createApp(() => probeNativeEngine({
    baseUrl: config.openCode.baseUrl,
    password: config.openCode.password,
  }), {
    service: workflow,
    sessionToken,
    experience,
    workspace,
    access: config.access,
  }, { mode: config.mode });
}

import { spawn, type ChildProcess } from "node:child_process";
import { resolve } from "node:path";
import { resolveRuntimeConfig } from "./config.ts";

const config = resolveRuntimeConfig(process.env);
let openCode: ChildProcess | null = null;

if (config.mode !== "demo") {
  const REDACTED = REDACTED;
  if (!REDACTED) throw new Error("OPENCODE_PASSWORD is required for a live runtime.");
  const port = process.env.OPENCODE_PORT?.trim() || "4096";
  const dataHome = process.env.OPENCODE_DATA_HOME?.trim() || resolve(config.dataDirectory, "xdg-data");
  const configHome = process.env.OPENCODE_CONFIG_HOME?.trim() || resolve(config.dataDirectory, "xdg-config");
  const executable = resolve("node_modules/@opencode/cli-linux-x64-baseline/bin/opencode");
  openCode = spawn(executable, ["serve", "--hostname", "127.0.0.1", "--port", port], {
    cwd: process.cwd(),
    stdio: "inherit",
    env: {
      ...process.env,
      OPENCODE_PASSWORD: REDACTED,
      OPENCODE_SERVER_PASSWORD: REDACTED,
      XDG_DATA_HOME: dataHome,
      XDG_CONFIG_HOME: configHome,
    },
  });
}

await import("./instrument.ts");
const { server } = await import("./index.ts");
let shuttingDown = false;

function stop(exitCode: number, signal: NodeJS.Signals = "SIGTERM") {
  if (shuttingDown) return;
  shuttingDown = true;
  openCode?.kill(signal);
  server.close(() => process.exit(exitCode));
  setTimeout(() => process.exit(exitCode), 10_000).unref();
}

process.once("SIGTERM", () => stop(0, "SIGTERM"));
process.once("SIGINT", () => stop(0, "SIGINT"));

if (openCode) {
  openCode.once("error", (error) => {
    console.error("OpenCode failed to start.", error);
    stop(1);
  });
  openCode.once("exit", (code, signal) => {
    if (shuttingDown) return;
    console.error(`OpenCode exited unexpectedly (${signal ?? code ?? "unknown"}).`);
    stop(code && code > 0 ? code : 1);
  });
}

