import { useEffect, useState, type FormEvent } from "react";
import { Eye, Hammer, ScrollText, Sparkles } from "lucide-react";
import { motion, useReducedMotion } from "motion/react";
import { MODE_DESCRIPTORS, runtimeModes, type ModeDescriptor } from "../shared/modes.ts";
import {
  ApiError,
  approveProduct,
  approveSection,
  grantScope,
  loadEngine,
  loadExport,
  loadMode,
  loadProject,
  loadWorkspace,
  reconcileRun,
  reviseSection,
  runMaker,
  selectWorkspace,
  sendMessage,
  type EngineStatus,
  type ModeResponse,
  type WorkspaceStatus,
  type WorkshopProject,
} from "./api.ts";

const spirits = [
  ["ORACLE", "Oracle", Sparkles],
  ["ARCHITECT", "Architect", ScrollText],
  ["MAKER", "Maker", Hammer],
  ["WITNESS", "Witness", Eye],
] as const;

export function App() {
  const [project, setProject] = useState<WorkshopProject | null>(null);
  const [engine, setEngine] = useState<EngineStatus | null>(null);
  const [runtime, setRuntime] = useState<ModeResponse | null>(null);
  const [workspace, setWorkspace] = useState<WorkspaceStatus | null>(null);
  const [text, setText] = useState("");
  const [scope, setScope] = useState("Build the approved plan in the selected workspace and leave a passing Node test.");
  const [change, setChange] = useState("");
  const [busy, setBusy] = useState(false);
  const [slow, setSlow] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [exportNote, setExportNote] = useState<string | null>(null);
  const [setupOpen, setSetupOpen] = useState(false);
  const [workspacePath, setWorkspacePath] = useState("");
  const [workspaceBusy, setWorkspaceBusy] = useState(false);
  const [workspaceNote, setWorkspaceNote] = useState<string | null>(null);
  const reduceMotion = useReducedMotion();

  useEffect(() => {
    void Promise.all([loadProject(), loadEngine(), loadMode()])
      .then(async ([loaded, native, loadedMode]) => {
        setProject(loaded);
        setEngine(native);
        setRuntime(loadedMode);
        if (loadedMode.mode !== "demo") {
          setWorkspace(await loadWorkspace().catch(() => null));
        }
      })
      .catch((caught: unknown) => {
        setError(caught instanceof Error ? caught.message : "The workshop could not be loaded.");
      });
  }, []);

  const readOnly = runtime?.descriptor.capabilities.find((item) => item.id === "mutations")?.available === false;
  const readOnlyReason = readOnly ? runtime?.descriptor.unavailableActions.mutations ?? "This action is unavailable." : null;

  async function act(work: () => Promise<{ project: WorkshopProject }>) {
    if (readOnly) {
      setError(readOnlyReason);
      return;
    }
    setBusy(true);
    setSlow(false);
    setError(null);
    const timer = window.setTimeout(() => setSlow(true), 8_000);
    try {
      setProject((await work()).project);
    } catch (caught) {
      const loaded = await loadProject().catch(() => null);
      if (loaded) setProject(loaded);
      setError(caught instanceof ApiError
        ? `${caught.message} ${caught.retryable ? "You can try a new request. The current section was not overwritten." : "Nothing was repeated."}`
        : "The workshop lost its connection. Reload before trying again.");
    } finally {
      window.clearTimeout(timer);
      setBusy(false);
      setSlow(false);
    }
  }

  async function applyWorkspace(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!project) return;
    setWorkspaceBusy(true);
    setWorkspaceNote(null);
    try {
      const result = await selectWorkspace(project, workspacePath.trim());
      setProject(result.project);
      const updated = await loadWorkspace();
      setWorkspace(updated);
      setWorkspacePath("");
      setWorkspaceNote(`Workspace set to ${updated.current ?? "the selected directory"}.`);
    } catch (caught) {
      setWorkspaceNote(caught instanceof Error ? caught.message : "The workspace could not be selected.");
    } finally {
      setWorkspaceBusy(false);
    }
  }

  if (!project) {
    return (
      <main className="workshop">
        <h1>Unfinished Business</h1>
        <p>{error ?? "The workshop is waking up."}</p>
      </main>
    );
  }

  const section = project.sections.find((item) => item.id === project.currentSectionId) ?? null;
  const unknown = project.operations.find((item) => item.status === "UNKNOWN") ?? null;
  const header = project.stage === "ORACLE"
    ? "What's still haunting your to-do list?"
    : section
      ? `${section.title} — section ${section.order} of ${project.sections.length}`
      : project.nextAction;

  return (
    <>
      <a className="skip" href="#document">Skip to the working document</a>
      <main className="workshop">
        <header className="mode-bar">
          <span className={`mode-badge mode-${runtime?.mode ?? "unknown"}`}>
            {runtime?.descriptor.badge ?? "Mode unavailable"}
          </span>
          <p className="mode-summary">{runtime?.descriptor.summary ?? "The runtime mode could not be loaded."}</p>
          <button className="action secondary" type="button" aria-expanded={setupOpen} onClick={() => setSetupOpen((open) => !open)}>
            Modes &amp; setup
          </button>
        </header>
        {setupOpen && runtime ? (
          <ModeSetup
            current={runtime}
            workspace={workspace}
            workspacePath={workspacePath}
            setWorkspacePath={setWorkspacePath}
            applyWorkspace={applyWorkspace}
            workspaceBusy={workspaceBusy}
            workspaceNote={workspaceNote}
          />
        ) : null}
        {runtime?.mode === "demo" ? (
          <p className="banner demo" role="status">
            <strong>Hosted demo · deterministic sample · read-only.</strong>{" "}
            No repository, OpenCode session, provider key, or user data is connected.
            <button className="action secondary inline" type="button" onClick={() => window.location.reload()}>Reset demo</button>
          </p>
        ) : null}
        {readOnlyReason ? <p className="banner bad" role="status">{readOnlyReason}</p> : null}
        <nav className="stage-strip" aria-label="Spirits">
          {spirits.map(([id, label, Icon]) => {
            const done = stageOrder(project.stage) > stageOrder(id);
            return (
              <button key={id} type="button" className={done ? "stage done" : "stage"} aria-current={project.stage === id ? "step" : undefined} disabled>
                <Icon aria-hidden="true" size={18} />
                {label}
              </button>
            );
          })}
        </nav>
        <div className="frame">
          <aside className="side">
            <section className="panel">
              <h2>Outline</h2>
              <ol>
                {project.sections.map((item) => (
                  <li key={item.id} className={item.status === "STALE" ? "ghost" : undefined}>
                    {item.title} — {statusLabel(item)}
                  </li>
                ))}
              </ol>
            </section>
          </aside>
          <article className="document" id="document" aria-busy={busy}>
            <Lantern />
            <p className="eyebrow">{project.stage}</p>
            <h1>
              {header}
              {project.product.status === "APPROVED" && section?.status === "APPROVED" ? (
                <Seal label="Approved" reduceMotion={reduceMotion} />
              ) : null}
            </h1>
            <p className="status-line">Stopped here: {project.nextAction}</p>
            {engine && !engine.available && runtime?.mode !== "demo" ? (
              <p className="banner bad" role="status">
                {engine.limitation?.includes("fetch failed")
                  ? "OpenCode is not reachable on the configured loopback address."
                  : engine.limitation}{" "}
                Start OpenCode, then try again. No paid model will be used.
              </p>
            ) : null}
            {unknown ? (
              <p className="banner bad" role="status">
                A native run is unknown and was not repeated.
                <button className="action secondary" type="button" disabled={busy || readOnly} onClick={() => void act(() => reconcileRun(project, unknown.id))}>Reconcile native session</button>
              </p>
            ) : null}
            {slow ? <p className="banner" role="status">This is taking longer than usual. The saved section is unchanged until a response arrives.</p> : null}
            {error ? <p className="banner bad" role="alert">{error}</p> : null}

            {project.stage === "ORACLE" ? (
              <OraclePanel project={project} text={text} setText={setText} busy={busy} readOnly={readOnly} act={act} />
            ) : null}
            {project.stage === "ARCHITECT" && section ? (
              <ArchitectPanel
                project={project}
                section={section}
                change={change}
                setChange={setChange}
                text={text}
                setText={setText}
                busy={busy}
                readOnly={readOnly}
                act={act}
                reduceMotion={reduceMotion}
              />
            ) : null}
            {project.stage === "ARCHITECT" && !section ? (
              <ScopePanel project={project} scope={scope} setScope={setScope} busy={busy} readOnly={readOnly} act={act} />
            ) : null}
            {project.stage === "MAKER" ? (
              <MakerPanel project={project} busy={busy} readOnly={readOnly} act={act} />
            ) : null}
            {project.stage === "WITNESS" ? (
              <WitnessPanel project={project} text={text} setText={setText} busy={busy} readOnly={readOnly} act={act} exportNote={exportNote} setExportNote={setExportNote} />
            ) : null}
          </article>
          <aside className="side">
            <Activity project={project} />
          </aside>
        </div>
      </main>
    </>
  );
}

function ModeSetup(props: {
  current: ModeResponse;
  workspace: WorkspaceStatus | null;
  workspacePath: string;
  setWorkspacePath: (value: string) => void;
  applyWorkspace: (event: FormEvent<HTMLFormElement>) => Promise<void>;
  workspaceBusy: boolean;
  workspaceNote: string | null;
}) {
  return (
    <section className="setup" aria-labelledby="setup-heading">
      <h2 id="setup-heading">Runtime modes and setup</h2>
      <p>
        The mode is chosen when the server starts. The browser cannot switch modes or reach a visitor&apos;s local files.
        Each mode keeps a distinct privacy and cost boundary.
      </p>
      <div className="mode-grid">
        {runtimeModes.map((mode) => {
          const descriptor = MODE_DESCRIPTORS[mode];
          const current = props.current.mode === mode;
          return (
            <article key={mode} className={current ? "mode-card current" : "mode-card"}>
              <h3>{descriptor.label}{current ? <span className="meta"> current</span> : null}</h3>
              <p>{descriptor.summary}</p>
              <ul className="capabilities" aria-label={`${descriptor.label} capabilities`}>
                {descriptor.capabilities.map((capability) => (
                  <li key={capability.id} className={capability.available ? "capability available" : "capability unavailable"}>
                    <strong>{capability.label}:</strong> {capability.available ? "available" : "not available"}. {capability.detail}
                  </li>
                ))}
              </ul>
              <ModeDetails title="Requirements" items={descriptor.requirements} />
              <ModeDetails title="Privacy consequences" items={descriptor.privacy} />
              <ModeDetails title="Cost notices" items={descriptor.cost} />
              <ModeDetails title="Recovery instructions" items={descriptor.recovery} />
            </article>
          );
        })}
      </div>
      {props.current.mode === "local" && props.workspace?.selectable ? (
        <form className="workspace-picker" onSubmit={(event) => void props.applyWorkspace(event)}>
          <h3>Select a local workspace</h3>
          <p className="note">
            Allowed root: <code>{props.workspace.root}</code>. Current: <code>{props.workspace.current}</code>.
            Relative paths stay inside this root; <code>..</code>, absolute outside paths, symlink escapes, and private state directories are rejected.
          </p>
          <label>
            Workspace path
            <input
              value={props.workspacePath}
              onChange={(event) => props.setWorkspacePath(event.target.value)}
              placeholder="relative/path or an absolute path inside the root"
              maxLength={4096}
            />
          </label>
          <button className="action" type="submit" disabled={props.workspaceBusy || props.workspacePath.trim().length === 0}>
            Use this workspace
          </button>
          {props.workspaceNote ? <p className="banner" role="status">{props.workspaceNote}</p> : null}
        </form>
      ) : null}
      {props.current.mode === "local" && props.workspace && !props.workspace.selectable ? (
        <p className="banner">{props.workspace.reason ?? "Workspace selection is unavailable."}</p>
      ) : null}
    </section>
  );
}

function ModeDetails({ title, items }: { title: string; items: string[] }) {
  return (
    <details>
      <summary>{title}</summary>
      <ul>{items.map((item) => <li key={item}>{item}</li>)}</ul>
    </details>
  );
}

function OraclePanel(props: {
  project: WorkshopProject;
  text: string;
  setText: (value: string) => void;
  busy: boolean;
  readOnly: boolean;
  act: (work: () => Promise<{ project: WorkshopProject }>) => Promise<void>;
}) {
  const proposal = props.project.product.proposal;
  return (
    <>
      <p>Describe an idea you want to bring to life.</p>
      {proposal ? (
        <div className="reading prose">
          <h2>Oracle proposal</h2>
          <p>{proposal}</p>
          {props.project.product.openQuestions.length ? (
            <ul>{props.project.product.openQuestions.map((question) => <li key={question}>{question}</li>)}</ul>
          ) : null}
        </div>
      ) : null}
      <label>
        Idea or question
        <textarea value={props.text} onChange={(event) => props.setText(event.target.value)} maxLength={8000} />
      </label>
      <div className="actions">
        {proposal ? (
          <button className="action" type="button" disabled={props.busy || props.readOnly} onClick={() => void props.act(() => approveProduct(props.project))}>
            Approve product
          </button>
        ) : (
          <button className="action" type="button" disabled={props.busy || props.readOnly || props.text.trim().length < 1} onClick={() => void props.act(() => sendMessage(props.project, "clarify", props.text))}>
            Wake the Oracle
          </button>
        )}
        {proposal ? (
          <button className="action secondary" type="button" disabled={props.busy || props.readOnly || props.text.trim().length < 1} onClick={() => void props.act(() => sendMessage(props.project, "question", props.text))}>
            Ask a question
          </button>
        ) : null}
      </div>
    </>
  );
}

function ArchitectPanel(props: {
  project: WorkshopProject;
  section: WorkshopProject["sections"][number];
  change: string;
  setChange: (value: string) => void;
  text: string;
  setText: (value: string) => void;
  busy: boolean;
  readOnly: boolean;
  reduceMotion: boolean | null;
  act: (work: () => Promise<{ project: WorkshopProject }>) => Promise<void>;
}) {
  return (
    <>
      <p className="meta">{props.section.status} · version {props.section.version}</p>
      {props.section.status === "STALE" ? <p className="banner">An upstream change marked this section stale. Review it again before approval counts.</p> : null}
      <div className="reading prose">
        {props.section.content || "This section has no draft yet."}
      </div>
      {props.section.status === "APPROVED" ? <Seal label="Section approved" reduceMotion={props.reduceMotion} /> : null}
      <div className="actions">
        <button className="action" type="button" disabled={props.busy || props.readOnly} onClick={() => void props.act(() => sendMessage(props.project, "draft", props.text.trim() || `Draft ${props.section.title}`))}>
          Draft section
        </button>
        {props.section.status === "DRAFT" ? (
          <button className="action secondary" type="button" disabled={props.busy || props.readOnly} onClick={() => void props.act(() => approveSection(props.project, props.section.version, props.section.hash, props.section.id))}>
            Approve section
          </button>
        ) : null}
      </div>
      <label>
        Ask a question
        <textarea value={props.text} onChange={(event) => props.setText(event.target.value)} maxLength={8000} />
      </label>
      <button className="action secondary" type="button" disabled={props.busy || props.readOnly || props.text.trim().length < 1} onClick={() => void props.act(() => sendMessage(props.project, "question", props.text))}>
        Ask
      </button>
      <label>
        Replacement text for this section
        <textarea value={props.change} onChange={(event) => props.setChange(event.target.value)} maxLength={8000} />
      </label>
      <button className="action secondary" type="button" disabled={props.busy || props.readOnly || props.change.trim().length < 1} onClick={() => void props.act(() => reviseSection(props.project, props.section.id, props.change))}>
        Request changes
      </button>
    </>
  );
}

function ScopePanel(props: {
  project: WorkshopProject;
  scope: string;
  setScope: (value: string) => void;
  busy: boolean;
  readOnly: boolean;
  act: (work: () => Promise<{ project: WorkshopProject }>) => Promise<void>;
}) {
  return (
    <>
      <p>Every current section is approved. Maker still needs a separate scope before any native edit.</p>
      <label>
        Maker scope
        <textarea value={props.scope} onChange={(event) => props.setScope(event.target.value)} maxLength={2000} />
      </label>
      <button className="action" type="button" disabled={props.busy || props.readOnly || props.scope.trim().length < 8} onClick={() => void props.act(() => grantScope(props.project, props.scope.trim()))}>
        Grant Maker scope
      </button>
    </>
  );
}

function MakerPanel(props: {
  project: WorkshopProject;
  busy: boolean;
  readOnly: boolean;
  act: (work: () => Promise<{ project: WorkshopProject }>) => Promise<void>;
}) {
  const recommended = props.project.capabilities.find((item) => item.id === "node-check");
  return (
    <>
      <p>Scope: {props.project.makerScope.statement}</p>
      <p>Workspace: <code>{props.project.workspace}</code></p>
      {recommended ? (
        <p className="banner">Recommended path: {recommended.purpose}. {recommended.nativeMapping}. Permission: {recommended.permission}.</p>
      ) : null}
      <button className="action" type="button" disabled={props.busy || props.readOnly} onClick={() => void props.act(() => runMaker(props.project))}>
        Run Maker
      </button>
    </>
  );
}

function WitnessPanel(props: {
  project: WorkshopProject;
  text: string;
  setText: (value: string) => void;
  busy: boolean;
  readOnly: boolean;
  act: (work: () => Promise<{ project: WorkshopProject }>) => Promise<void>;
  exportNote: string | null;
  setExportNote: (value: string | null) => void;
}) {
  return (
    <>
      <p>Witness reads the evidence in a fresh session and writes review notes. Those notes are not a submitted article or video.</p>
      <label>
        What should Witness examine?
        <textarea value={props.text} onChange={(event) => props.setText(event.target.value)} maxLength={8000} />
      </label>
      <div className="actions">
        <button className="action" type="button" disabled={props.busy || props.readOnly || props.text.trim().length < 1} onClick={() => void props.act(() => sendMessage(props.project, "witness", props.text))}>
          Review evidence
        </button>
        <button className="action secondary" type="button" disabled={props.busy} onClick={() => void loadExport().then((exported) => props.setExportNote(exported.limitation + (exported.plan ? " Compiled plan is ready." : " Plan is not fully approved."))).catch((caught: unknown) => props.setExportNote(caught instanceof Error ? caught.message : "Export failed."))}>
          Check export
        </button>
      </div>
      {props.exportNote ? <p className="banner" role="status">{props.exportNote}</p> : null}
      {props.project.witnessDrafts.map((draft) => (
        <section key={draft.id} className="reading">
          <h2>{draft.title}</h2>
          <p className="prose">{draft.content}</p>
        </section>
      ))}
    </>
  );
}

function Activity({ project }: { project: WorkshopProject }) {
  const latest = [...project.operations].reverse().slice(0, 4);
  return (
    <>
      <section className="panel">
        <h2>Activity</h2>
        {latest.length === 0 ? <p>No native run yet.</p> : (
          <ul>
            {latest.map((item) => (
              <li key={item.id}>
                <span className="meta">{item.kind} · {item.status}</span>
                <div className="evidence">{(item.result ?? "No result recorded.").slice(0, 280)}</div>
              </li>
            ))}
          </ul>
        )}
      </section>
      <section className="panel">
        <h2>Evidence</h2>
        {project.evidence.length === 0 ? <p>No check has been observed.</p> : (
          <ul>
            {project.evidence.map((item) => (
              <li key={item.id}>{item.checkId}: {item.result}{item.limitation ? ` — ${item.limitation}` : ""}</li>
            ))}
          </ul>
        )}
      </section>
    </>
  );
}

function Seal({ label, reduceMotion }: { label: string; reduceMotion: boolean | null }) {
  if (reduceMotion) return <span className="seal">{label}</span>;
  return <motion.span className="seal" initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: 0.35 }}>{label}</motion.span>;
}

function Lantern() {
  return (
    <svg className="lantern" viewBox="0 0 32 32" aria-hidden="true">
      <rect x="12" y="3" width="8" height="3" rx="1" fill="#f4b66c" />
      <path d="M10 8h12l-1 16H11L10 8z" fill="#252031" stroke="#f4b66c" />
      <circle className="flame" cx="16" cy="16" r="3" fill="#f4b66c" />
    </svg>
  );
}

function statusLabel(section: WorkshopProject["sections"][number]): string {
  if (section.status === "DRAFT") return `Draft v${section.version}`;
  if (section.status === "NOT_STARTED") return "Not started";
  if (section.status === "APPROVED") return "Approved";
  return "Stale";
}

function stageOrder(stage: WorkshopProject["stage"]): number {
  return spirits.findIndex(([id]) => id === stage);
}

