import assert from "node:assert/strict";
import { mkdir, mkdtemp, readFile, realpath, symlink, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import test from "node:test";
import { createApp } from "../src/server/app.ts";
import { ConfigError, resolveRuntimeConfig } from "../src/server/config.ts";
import { createDemoProject } from "../src/server/demo/fixture.ts";
import { probeNativeEngine } from "../src/server/REDACTED/client.ts";
import { AtomicProjectStore } from "../src/server/store/atomic-project-store.ts";
import { WorkspaceError, WorkspacePolicy, WorkspaceService } from "../src/server/workspace.ts";
import { createProject } from "../src/server/workflow/model.ts";
import { WorkflowService } from "../src/server/workflow/service.ts";
import { capabilityOf, modeDescriptor, runtimeModes } from "../src/shared/modes.ts";

const engine = async () => ({
  available: true,
  serverVersion: "2.0.32",
  model: "REDACTED/deepseek-v4.1-flash-free" as const,
  modelAvailable: true,
  limitation: null,
});

async function localFixture() {
  const root = await realpath(await mkdtemp(join(tmpdir(), "ub-modes-")));
  const repo = join(root, "repo");
  const state = join(root, ".unfinished-business");
  await mkdir(repo);
  await mkdir(state);
  const store = new AtomicProjectStore(join(state, "project.json"));
  await store.initialize(createProject(root));
  const workflow = new WorkflowService(store);
  const policy = new WorkspacePolicy({
    root,
    mode: "local",
    selectable: true,
    protectedDirectories: [state],
  });
  const workspace = new WorkspaceService(workflow, policy);
  const app = createApp(engine, {
    service: workflow,
    sessionToken: "test-token",
    workspace,
  }, { mode: "local" });
  return { app, root, repo, state, workflow, policy, workspace };
}

test("each runtime mode has explicit capabilities and setup guidance", () => {
  for (const mode of runtimeModes) {
    const descriptor = modeDescriptor(mode);
    assert.equal(descriptor.id, mode);
    assert.ok(descriptor.requirements.length > 0);
    assert.ok(descriptor.privacy.length > 0);
    assert.ok(descriptor.cost.length > 0);
    assert.ok(descriptor.recovery.length > 0);
    assert.ok(descriptor.unavailableActions.mutations.length > 20);
  }

  assert.equal(capabilityOf("local", "repository").available, true);
  assert.equal(capabilityOf("local", "REDACTED").available, true);
  assert.equal(capabilityOf("local", "workspace").available, true);
  assert.equal(capabilityOf("local", "mutations").available, true);

  assert.equal(capabilityOf("demo", "repository").available, false);
  assert.equal(capabilityOf("demo", "REDACTED").available, false);
  assert.equal(capabilityOf("demo", "workspace").available, false);
  assert.equal(capabilityOf("demo", "mutations").available, false);
  assert.equal(capabilityOf("demo", "REDACTEDs").available, false);

  assert.equal(capabilityOf("private-hosted", "repository").available, true);
  assert.equal(capabilityOf("private-hosted", "REDACTED").available, true);
  assert.equal(capabilityOf("private-hosted", "workspace").available, false);
  assert.equal(capabilityOf("private-hosted", "persistence").available, true);
  assert.match(modeDescriptor("private-hosted").summary, /never in a visitor's local repository/i);
});

test("local configuration defaults to loopback and rejects unsafe exposure", () => {
  const config = resolveRuntimeConfig({ UB_RUNTIME_MODE: "local" });
  assert.equal(config.mode, "local");
  assert.equal(config.hostname, "127.0.0.1");
  assert.equal(config.openCode.baseUrl, "http://127.0.0.1:4096");

  assert.throws(
    () => resolveRuntimeConfig({ UB_RUNTIME_MODE: "local", UB_HOST: "0.0.0.0" }),
    /UB_ACCESS_PASSWORD/,
  );
  assert.throws(
    () => resolveRuntimeConfig({ UB_RUNTIME_MODE: "local", OPENCODE_BASE_URL: "https://example.com" }),
    /loopback/,
  );
  assert.doesNotThrow(() => resolveRuntimeConfig({
    UB_RUNTIME_MODE: "local",
    OPENCODE_BASE_URL: "https://example.com",
    UB_ALLOW_REMOTE_OPENCODE: "true",
  }));
});

test("demo configuration needs no REDACTEDs", () => {
  const config = resolveRuntimeConfig({ UB_RUNTIME_MODE: "demo" });
  assert.equal(config.mode, "demo");
  assert.equal(config.REDACTED, undefined);
  assert.equal(config.openCode.password, undefined);
});

test("private hosted configuration validates REDACTEDs and persistent storage without printing values", () => {
  assert.throws(
    () => resolveRuntimeConfig({ UB_RUNTIME_MODE: "private-hosted" }),
    (error) => error instanceof ConfigError
      && /UB_ACCESS_PASSWORD/.test(error.message)
      && /OPENCODE_PASSWORD/.test(error.message)
      && /UB_DATA_DIR/.test(error.message),
  );

  assert.throws(
    () => resolveRuntimeConfig({
      UB_RUNTIME_MODE: "private-hosted",
      UB_ACCESS_PASSWORD: "REDACTED",
      UB_DATA_DIR: "/var/data/unfinished-business",
    }),
    (error) => error instanceof ConfigError
      && /OPENCODE_PASSWORD/.test(error.message)
      && !error.message.includes("REDACTED"),
  );

  assert.throws(
    () => resolveRuntimeConfig({
      UB_RUNTIME_MODE: "private-hosted",
      UB_ACCESS_PASSWORD: "REDACTED",
      OPENCODE_PASSWORD: "REDACTED",
      UB_DATA_DIR: join(tmpdir(), "ub-private"),
    }),
    /temporary directory/,
  );

  assert.throws(
    () => resolveRuntimeConfig({
      UB_RUNTIME_MODE: "private-hosted",
      UB_ACCESS_PASSWORD: "REDACTED",
      OPENCODE_PASSWORD: "REDACTED",
      UB_DATA_DIR: "/var/data/unfinished-business",
      UB_WORKSPACE_ROOT: "/var/data/elsewhere",
    }),
    /inside UB_DATA_DIR/,
  );

  const config = resolveRuntimeConfig({
    UB_RUNTIME_MODE: "private-hosted",
    UB_ACCESS_PASSWORD: "REDACTED",
    OPENCODE_PASSWORD: "REDACTED",
    UB_DATA_DIR: "/var/data/unfinished-business",
  });
  assert.equal(config.mode, "private-hosted");
  assert.equal(config.workspaceRoot, "/var/data/unfinished-business/workspace");
  assert.equal(config.REDACTED?.username, "unfinished-business");
});

test("workspace policy accepts only directories inside the configured root", async () => {
  const root = await realpath(await mkdtemp(join(tmpdir(), "ub-workspace-")));
  const repo = join(root, "repo");
  const outside = await realpath(await mkdtemp(join(tmpdir(), "ub-outside-")));
  const state = join(root, ".unfinished-business");
  await mkdir(repo);
  await mkdir(state);
  await writeFile(join(root, "file.txt"), "not a directory");
  await symlink(outside, join(root, "escape"));
  const policy = new WorkspacePolicy({
    root,
    mode: "local",
    selectable: true,
    protectedDirectories: [state],
  });

  assert.equal(await policy.resolve("repo"), repo);
  assert.equal(await policy.resolve(repo), repo);
  await assert.rejects(policy.resolve("../outside"), (error) => error instanceof WorkspaceError && error.code === "WORKSPACE_OUTSIDE_ROOT");
  await assert.rejects(policy.resolve("/etc"), (error) => error instanceof WorkspaceError && error.code === "WORKSPACE_OUTSIDE_ROOT");
  await assert.rejects(policy.resolve("escape"), (error) => error instanceof WorkspaceError && error.code === "WORKSPACE_OUTSIDE_ROOT");
  await assert.rejects(policy.resolve("file.txt"), (error) => error instanceof WorkspaceError && error.code === "WORKSPACE_NOT_DIRECTORY");
  await assert.rejects(policy.resolve("missing"), (error) => error instanceof WorkspaceError && error.code === "WORKSPACE_NOT_FOUND");
  await assert.rejects(policy.resolve(".unfinished-business"), (error) => error instanceof WorkspaceError && error.code === "WORKSPACE_PROTECTED");
});

test("private workspace policy is locked and still reports its managed path", async () => {
  const root = await realpath(await mkdtemp(join(tmpdir(), "ub-private-workspace-")));
  const store = new AtomicProjectStore(join(root, "state", "project.json"));
  await store.initialize(createProject(root));
  const workflow = new WorkflowService(store);
  const policy = new WorkspacePolicy({ root, mode: "private-hosted", selectable: false });
  const service = new WorkspaceService(workflow, policy);
  const status = await service.status();
  assert.equal(status.selectable, false);
  assert.equal(status.current, root);
  await assert.rejects(
    service.select("select", 0, root),
    (error) => error instanceof WorkspaceError && error.code === "WORKSPACE_LOCKED",
  );
});

test("hosted demo is deterministic, public, and rejects every mutation or REDACTED", async () => {
  let probes = 0;
  const app = createApp(async () => {
    probes += 1;
    return engine();
  }, undefined, { mode: "demo" });

  const healthResponse = await app.request("/api/health");
  assert.equal(healthResponse.status, 200);
  const health = await healthResponse.json();
  assert.deepEqual(health, { status: "ok", service: "unfinished-business", mode: "demo" });
  assert.deepEqual(Object.keys(health).sort(), ["mode", "service", "status"]);

  const modeResponse = await app.request("/api/mode");
  assert.equal(modeResponse.status, 200);
  const mode = await modeResponse.json();
  assert.equal(mode.descriptor.label, "Hosted demo");
  assert.match(mode.descriptor.unavailableActions.mutations, /read-only/i);
  assert.match(mode.descriptor.unavailableActions.repository, /cannot REDACTED/i);

  const project = await (await app.request("/api/project")).json();
  assert.deepEqual(project, createDemoProject());
  assert.equal(project.workspace, "demo://read-only");
  assert.equal(project.operations.length, 0);

  const workspace = await (await app.request("/api/workspace")).json();
  assert.equal(workspace.selectable, false);
  assert.equal(workspace.root, null);
  assert.equal(workspace.current, null);

  const engineResponse = await app.request("/api/engine");
  assert.equal(engineResponse.status, 200);
  assert.equal((await engineResponse.json()).available, false);
  assert.equal(probes, 0);

  assert.equal((await app.request("/api/session")).status, 403);

  const headers = { "content-type": "application/json" };
  const attempts = [
    ["/api/runs", { actionId: "run", expectedRevision: 0 }],
    ["/api/messages", { actionId: "msg", expectedRevision: 0, intent: "clarify", text: "hi", OPENCODE_PASSWORD: "REDACTED" }],
    ["/api/approvals", { actionId: "approve", expectedRevision: 0, kind: "product" }],
    ["/api/workspace", { actionId: "path", expectedRevision: 0, path: "../../etc", OPENCODE_PASSWORD: "REDACTED" }],
    ["/api/sections/control/revisions", { actionId: "revise", expectedRevision: 0, content: "scope" }],
    ["/api/runs/abc/cancel", { actionId: "cancel", expectedRevision: 0 }],
    ["/api/runs/abc/reconcile", { actionId: "reconcile", expectedRevision: 0 }],
  ] as const;
  for (const [path, body] of attempts) {
    const response = await app.request(path, { method: "POST", headers, body: JSON.stringify(body) });
    assert.equal(response.status, 403, path);
    const result = await response.json();
    assert.equal(result.code, "MODE_READ_ONLY", path);
    assert.match(result.message, /read-only|repository|REDACTED|disabled/i, path);
  }
  assert.equal(probes, 0);
});

test("local mode exposes a validated workspace and requires its session token", async () => {
  const { app, root, repo } = await localFixture();

  const mode = await (await app.request("/api/mode")).json();
  assert.equal(mode.mode, "local");
  assert.equal(mode.descriptor.label, "Full local");

  const status = await (await app.request("/api/workspace")).json();
  assert.equal(status.selectable, true);
  assert.equal(status.root, root);
  assert.equal(status.current, root);

  const headers = { "content-type": "application/json", "x-ub-session-token": "test-token" };
  const missingToken = await app.request("/api/workspace", {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ actionId: "no-token", expectedRevision: 0, path: "repo" }),
  });
  assert.equal(missingToken.status, 403);
  assert.equal((await missingToken.json()).code, "INVALID_SESSION");

  const selected = await app.request("/api/workspace", {
    method: "POST",
    headers,
    body: JSON.stringify({ actionId: "select", expectedRevision: 0, path: "repo" }),
  });
  assert.equal(selected.status, 200, JSON.stringify(await selected.clone().json()));
  assert.equal((await selected.json()).project.workspace, repo);

  for (const path of ["../outside", "/etc", "repo/../../outside"]) {
    const response = await app.request("/api/workspace", {
      method: "POST",
      headers,
      body: JSON.stringify({ actionId: `bad-${path}`, expectedRevision: 1, path }),
    });
    assert.equal(response.status, 400, path);
    assert.equal((await response.json()).code, "WORKSPACE_OUTSIDE_ROOT", path);
  }

  const protectedResponse = await app.request("/api/workspace", {
    method: "POST",
    headers,
    body: JSON.stringify({ actionId: "protected", expectedRevision: 1, path: ".unfinished-business" }),
  });
  assert.equal(protectedResponse.status, 403);
  assert.equal((await protectedResponse.json()).code, "WORKSPACE_PROTECTED");
});

test("local mode reports an unreachable OpenCode connection", async () => {
  const { app } = await localFixture();
  const unreachable = createApp(async () => ({
    available: false,
    serverVersion: null,
    model: "REDACTED/deepseek-v4.1-flash-free" as const,
    modelAvailable: false,
    limitation: "fetch failed to the loopback OpenCode address",
  }), {
    service: (await localFixture()).workflow,
    sessionToken: "test-token",
  }, { mode: "local" });

  const response = await unreachable.request("/api/engine");
  assert.equal(response.status, 503);
  assert.equal((await response.json()).available, false);
  assert.match((await (await app.request("/api/health")).json()).mode, /local/);

  const probed = await probeNativeEngine({ baseUrl: "http://127.0.0.1:1" });
  assert.equal(probed.available, false);
  assert.ok(probed.limitation);
});

test("private hosted keeps REDACTED protection and a fixed managed workspace", async () => {
  const root = await realpath(await mkdtemp(join(tmpdir(), "ub-private-http-")));
  const store = new AtomicProjectStore(join(root, "state", "project.json"));
  await store.initialize(createProject(root));
  const workflow = new WorkflowService(store);
  const workspace = new WorkspaceService(workflow, new WorkspacePolicy({
    root,
    mode: "private-hosted",
    selectable: false,
  }));
  const app = createApp(engine, {
    service: workflow,
    sessionToken: "test-token",
    workspace,
    REDACTED: { username: "builder", password: "REDACTED" },
  }, { mode: "private-hosted" });

  const healthResponse = await app.request("/api/health");
  assert.equal(healthResponse.status, 200);
  assert.deepEqual(await healthResponse.json(), {
    status: "ok",
    service: "unfinished-business",
    mode: "private-hosted",
  });

  const modeResponse = await app.request("/api/mode");
  assert.equal(modeResponse.status, 200);
  assert.equal((await modeResponse.json()).descriptor.label, "Private hosted deployment");

  assert.equal((await app.request("/api/project")).status, 401);
  const authorization = `Basic ${Buffer.from("builder:REDACTED").toString("base64")}`;
  assert.equal((await app.request("/api/project", { headers: { authorization } })).status, 200);

  const workspaceResponse = await app.request("/api/workspace", {
    method: "POST",
    headers: {
      authorization,
      "content-type": "application/json",
      "x-ub-session-token": "test-token",
    },
    body: JSON.stringify({ actionId: "select", expectedRevision: 0, path: "state" }),
  });
  assert.equal(workspaceResponse.status, 403);
  assert.equal((await workspaceResponse.json()).code, "WORKSPACE_LOCKED");
});

test("render blueprint and environment template match the documented modes", async () => {
  const blueprint = await readFile(new URL("../render.yaml", import.meta.url), "utf8");
  const example = await readFile(new URL("../.env.example", import.meta.url), "utf8");

  assert.match(blueprint, /key: UB_RUNTIME_MODE[\s\S]*?value: private-hosted/);
  assert.match(blueprint, /key: UB_DATA_DIR[\s\S]*?value: \/var\/data\/unfinished-business/);
  assert.match(blueprint, /key: UB_WORKSPACE_ROOT[\s\S]*?value: \/var\/data\/unfinished-business\/workspace/);
  assert.match(blueprint, /mountPath: \/var\/data/);
  assert.match(blueprint, /healthCheckPath: \/api\/health/);
  assert.match(blueprint, /plan: 0\.5c-512mb/);
  assert.equal((blueprint.match(/generateValue: true/g) ?? []).length >= 3, true);
  const buildCommand = blueprint.split("\n").find((line) => line.includes("buildCommand")) ?? "";
  assert.equal(/var\/data/.test(buildCommand), false);

  assert.match(example, /UB_RUNTIME_MODE=local/);
  assert.match(example, /UB_WORKSPACE_ROOT=/);
  assert.match(example, /UB_ACCESS_PASSWORD=REDACTED;
  assert.match(example, /OPENCODE_PASSWORD=REDACTED;
});

