import assert from "node:assert/strict";
import test from "node:test";
import { createElement } from "react";
import { renderToStaticMarkup } from "react-dom/server";
import { modeDescriptor } from "../src/shared/modes.ts";
import type { ModeResponse } from "../src/web/api.ts";
import { ModeBadge, ModeCapabilitySummary, ReadOnlyNotice } from "../src/web/mode-view.tsx";

const local: ModeResponse = { mode: "local", descriptor: modeDescriptor("local") };
const demo: ModeResponse = { mode: "demo", descriptor: modeDescriptor("demo") };
const hosted: ModeResponse = { mode: "private-hosted", descriptor: modeDescriptor("private-hosted") };

test("the rendered mode badge distinguishes all three modes", () => {
  assert.match(renderToStaticMarkup(createElement(ModeBadge, { runtime: local })), /Local · full execution/);
  assert.match(renderToStaticMarkup(createElement(ModeBadge, { runtime: demo })), /Demo · read-only sample/);
  assert.match(renderToStaticMarkup(createElement(ModeBadge, { runtime: hosted })), /Private hosted · protected/);
  assert.match(renderToStaticMarkup(createElement(ModeBadge, { runtime: null })), /Mode unavailable/);
});

test("the rendered capability summary reports repository, OpenCode, storage, and providers", () => {
  const summary = renderToStaticMarkup(createElement(ModeCapabilitySummary, { runtime: local }));
  assert.match(summary, /Repository: yes/);
  assert.match(summary, /OpenCode: yes/);
  assert.match(summary, /Storage: yes/);
  assert.match(summary, /Providers: yes/);

  const demoSummary = renderToStaticMarkup(createElement(ModeCapabilitySummary, { runtime: demo }));
  assert.match(demoSummary, /Repository: no/);
  assert.match(demoSummary, /OpenCode: no/);
  assert.match(demoSummary, /Storage: no/);
  assert.match(demoSummary, /Providers: no/);
});

test("the rendered read-only notice explains unavailable actions", () => {
  const notice = renderToStaticMarkup(createElement(ReadOnlyNotice, { runtime: demo }));
  assert.match(notice, /public hosted demo is read-only/i);
  assert.match(notice, /Run Unfinished Business locally/i);
  assert.equal(renderToStaticMarkup(createElement(ReadOnlyNotice, { runtime: local })), "");
  assert.equal(renderToStaticMarkup(createElement(ReadOnlyNotice, { runtime: hosted })), "");
});

