test("changing the local workspace marks prior evidence stale", async () => {
  const { workflow, workspace, repo } = await localFixture();
  const project = await workflow.execute("evidence", {}, 0, (current) => ({
    ...current,
    evidence: [{
      id: "evidence-1",
      checkId: "CK-06",
      nativeResultReference: "ses_native",
      testedFingerprint: "fingerprint",
      result: "PASS",
      observedAt: "2026-10-31T00:00:00.000Z",
      limitation: null,
    }],
  }));
  const selected = await workspace.select("move", project.revision, "repo");
  assert.equal(selected.project.workspace, repo);
  assert.equal(selected.project.evidence[0].result, "STALE");
  assert.match(selected.project.evidence[0].limitation ?? "", /workspace changed/i);
});

