import type { RuntimeMode } from "../shared/modes.ts";
import type { ModeResponse } from "./api.ts";

type SummaryCapabilityId = "repository" | "opencode" | "persistence" | "providers";

const summaryCapabilities: SummaryCapabilityId[] = ["repository", "opencode", "persistence", "providers"];

const shortLabels: Record<SummaryCapabilityId, string> = {
  repository: "Repository",
  opencode: "OpenCode",
  persistence: "Storage",
  providers: "Providers",
};

const summaryValues: Record<RuntimeMode, Record<SummaryCapabilityId, string>> = {
  local: {
    repository: "selected local",
    opencode: "live",
    persistence: "local disk",
    providers: "OpenCode",
  },
  demo: {
    repository: "none",
    opencode: "off",
    persistence: "none",
    providers: "off",
  },
  "private-hosted": {
    repository: "managed server",
    opencode: "live",
    persistence: "private disk",
    providers: "Render secrets",
  },
};

export function ModeBadge({ runtime }: { runtime: ModeResponse | null }) {
  return (
    <span className={`mode-badge mode-${runtime?.mode ?? "unknown"}`}>
      {runtime?.descriptor.badge ?? "Mode unavailable"}
    </span>
  );
}

export function ModeCapabilitySummary({ runtime }: { runtime: ModeResponse | null }) {
  if (!runtime) return null;
  return (
    <span className="mode-capabilities" aria-label="Mode capabilities">
      {summaryCapabilities.map((id) => `${shortLabels[id]}: ${summaryValues[runtime.mode][id]}`).join(" · ")}
    </span>
  );
}

export function ReadOnlyNotice({ runtime }: { runtime: ModeResponse | null }) {
  const mutations = runtime?.descriptor.capabilities.find((capability) => capability.id === "mutations");
  if (!runtime || mutations?.available !== false) return null;
  return <p className="banner bad" role="status">{runtime.descriptor.unavailableActions.mutations}</p>;
}

